package ch.local.autoscroll;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.media.*;import android.media.projection.*;import android.hardware.display.*;import android.os.*;import android.provider.MediaStore;import android.net.Uri;import android.util.DisplayMetrics;
public class RecordingService extends Service {
 static RecordingService instance; static String status="Idle"; static Uri lastVideo; MediaProjection projection; MediaRecorder recorder; VirtualDisplay display; ParcelFileDescriptor fd; Uri uri; boolean started=false,closing=false; int w,hh,density; final Runnable expire=()->finishCapture(); final Handler h=new Handler(Looper.getMainLooper());
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"stop".equals(i.getAction())){finishCapture();return START_NOT_STICKY;}if(i==null){stopSelf();return START_NOT_STICKY;} if(instance!=null){return START_NOT_STICKY;} instance=this;closing=false;try{
 NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("capture","Screen recording",NotificationManager.IMPORTANCE_LOW));
 Notification n=new Notification.Builder(this,"capture").setSmallIcon(android.R.drawable.ic_menu_camera).setContentTitle("AutoScroll").setContentText("Enregistrement sans audio").setOngoing(true).addAction(new Notification.Action.Builder(null,"Fermer la capture",PendingIntent.getService(this,8,new Intent(this,RecordingService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE)).build()).build();
 if(Build.VERSION.SDK_INT>=29)startForeground(7,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(7,n);
 Intent data=i.getParcelableExtra("data");projection=getSystemService(MediaProjectionManager.class).getMediaProjection(i.getIntExtra("result",0),data);
 projection.registerCallback(new MediaProjection.Callback(){public void onStop(){finishCapture();}},h);
 DisplayMetrics m=new DisplayMetrics();getSystemService(android.view.WindowManager.class).getDefaultDisplay().getRealMetrics(m);float scale=Math.min(1f,1080f/Math.min(m.widthPixels,m.heightPixels));w=((int)(m.widthPixels*scale)/2)*2;hh=((int)(m.heightPixels*scale)/2)*2;
 density=m.densityDpi;display=projection.createVirtualDisplay("Ricardo",w,hh,density,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,null,null,h);startClip();}catch(Exception e){finishCapture();}return START_NOT_STICKY;}
 void startClip(){if(closing||started)return;h.removeCallbacks(expire);try{
 ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,"Ricardo_"+new java.text.SimpleDateFormat("yyyyMMdd_HHmmss",java.util.Locale.US).format(new java.util.Date())+".mp4");v.put(MediaStore.MediaColumns.MIME_TYPE,"video/mp4");v.put(MediaStore.MediaColumns.RELATIVE_PATH,"Download/Ricardo AutoScroll");v.put(MediaStore.MediaColumns.IS_PENDING,1);uri=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);fd=getContentResolver().openFileDescriptor(uri,"w");
 recorder=new MediaRecorder();recorder.setVideoSource(MediaRecorder.VideoSource.SURFACE);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setVideoEncoder(MediaRecorder.VideoEncoder.H264);recorder.setVideoSize(w,hh);recorder.setVideoFrameRate(30);recorder.setVideoEncodingBitRate(3500000);recorder.setOutputFile(fd.getFileDescriptor());recorder.prepare();display.setSurface(recorder.getSurface());recorder.start();started=true;status="Recording";if(ScrollService.instance!=null)ScrollService.instance.captureReady();else finishCapture();
 }catch(Exception e){status="Capture failed: "+e.getClass().getSimpleName();finishCapture();}}
 void stopClip(){boolean ok=false;if(started)try{recorder.stop();ok=true;}catch(RuntimeException ignored){}started=false;if(display!=null)display.setSurface(null);if(recorder!=null)recorder.release();recorder=null;try{if(fd!=null)fd.close();if(uri!=null){if(ok){ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.IS_PENDING,0);getContentResolver().update(uri,v,null,null);lastVideo=uri;getSharedPreferences("cfg",0).edit().putString("lastVideo",uri.toString()).apply();status="Saved";new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(this,"Vidéo sauvegardée dans Downloads",android.widget.Toast.LENGTH_LONG).show());}else getContentResolver().delete(uri,null,null);}}catch(Exception ignored){}uri=null;fd=null;h.removeCallbacks(expire);if(!closing)h.postDelayed(expire,300000);}
 void finishCapture(){if(closing)return;closing=true;h.removeCallbacks(expire);stopClip();if(display!=null)display.release();if(projection!=null)projection.stop();instance=null;if(ScrollService.instance!=null)ScrollService.instance.finish();stopForeground(true);stopSelf();}
 public void onDestroy(){finishCapture();super.onDestroy();}
}